spec = {"max_characters": 500, "allowed_labels": {"billing", "account", "review"}}
def validate(message, prediction):
    return (isinstance(message, str) and 0 < len(message.strip()) <= spec["max_characters"]
            and prediction in spec["allowed_labels"])
checks = [("Invoice question", "billing"), ("", "account"), ("Hello", "unknown")]
for text, label in checks:
    print(validate(text, label))
